 "alice-apple-tree/AppleTreeFormula.java": "import java.util.Scanner;\n\npublic class AppleTreeFormula {\n    // Apples inside the square of half-side r:  2 r (r + 1) (2 r + 1)   (= 4r^3 + 6r^2 + 2r)\n    static long applesInside(long r) {\n        return 2 * r * (r + 1) * (2 * r + 1);\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        long needed = sc.nextLong();\n        long lo = 1;\n        long hi = 200_000;                    // 2 * 200000 * 200001 * 400001 > 3 * 10^16, enough for needed <= 10^15\n        while (lo < hi) {                     // smallest r with applesInside(r) >= needed\n            long mid = (lo + hi) / 2;\n            if (applesInside(mid) >= needed) {\n                hi = mid;\n            } else {\n                lo = mid + 1;\n            }\n        }\n        System.out.println(8 * lo);\n    }\n}\n",
 "alice-apple-tree/AppleTreeLoop.java": "import java.util.Scanner;\n\npublic class AppleTreeLoop {\n    // Alice stands at the origin of an infinite grid; the tree at (i, j) has |i| + |j| apples.\n    // She buys a square plot [-r, r] x [-r, r] (perimeter 8r) and keeps every apple inside.\n    // The apples in the NEW ring when the plot grows from r-1 to r are exactly 12 * r * r.\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        long needed = sc.nextLong();\n        long r = 0;\n        long apples = 0;\n        while (apples < needed) {\n            r++;\n            apples += 12 * r * r;       // add the ring at distance r\n        }\n        System.out.println(\"half-side r = \" + r + \", total apples = \" + apples + \", minimum perimeter = \" + 8 * r);\n    }\n}\n",
 "alice-apple-tree/Ex1.java": "import java.util.Scanner;\n\npublic class Ex1 {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        long r = sc.nextLong();\n        System.out.println(2 * r * (r + 1) * (2 * r + 1));\n    }\n}\n",
